Interpolate premultiplied:
Color kkMix(Color a, double amount, Color b) {
  final double t = amount.clamp(0.0, 1.0);
  final double wa = a.a * t, wb = b.a * (1 - t), alpha = wa + wb;
  if (alpha <= 0) return const Color(0x00000000);
  return Color.from(alpha: alpha, red: (a.r * wa + b.r * wb) / alpha, green: (a.g * wa + b.g * wb) / alpha, blue: (a.b * wa + b.b * wb) / alpha);
